import sys
import time
from pathlib import Path

import pandas as pd

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from utils.analytics import answer_analytics_question


DATASET_PATH = (
    PROJECT_ROOT
    / "data"
    / "evaluations"
    / "benchmark_retail.csv"
)


QUESTIONS = [
    "Which campaign generated the highest Revenue in the dataset?",
    "Which campaign had the strongest ROI among the records?",
    "What is the total Revenue generated by records 47 and 74?",
    "What is the average Revenue of records 36 and 96?",
    "Which record generated more Revenue, record 36 or record 96?",
    "Which record generated more Revenue, record 60 or record 100?",
    "Find the campaign in the North region with Revenue of 100500.",
    "Find the campaign in the South region with Revenue of 110000.",
    "What are the main business insights you can identify from the uploaded retail dataset?",
]


def main():

    print("=" * 70)
    print("RetailGenAI 2.0 - EXPERIMENT 9")
    print("Dataset-Level Analytics Routing")
    print("=" * 70)

    df = pd.read_csv(DATASET_PATH)

    print(f"Dataset records: {len(df)}")
    print(f"Questions: {len(QUESTIONS)}")

    handled = 0
    rag_required = 0

    results = []

    for i, question in enumerate(QUESTIONS, 1):

        start = time.perf_counter()

        result = answer_analytics_question(
            df,
            question
        )

        latency = time.perf_counter() - start

        if result["handled"]:
            handled += 1
            route = "DETERMINISTIC"
        else:
            rag_required += 1
            route = "RAG / LLM"

        results.append({
            "question": question,
            "route": route,
            "latency": latency,
            "answer": result.get("answer"),
        })

        print("\n" + "-" * 70)
        print(f"[{i}] {question}")
        print(f"Route: {route}")
        print(f"Latency: {latency:.6f}s")

        if result["handled"]:
            print(f"Answer: {result['answer']}")
        else:
            print("Answer: Requires RAG / LLM")

    total = len(QUESTIONS)

    print("\n" + "=" * 70)
    print("EXPERIMENT 9 RESULTS")
    print("=" * 70)

    print(f"Total questions:       {total}")
    print(f"Deterministic:         {handled}")
    print(f"RAG / LLM required:    {rag_required}")

    print(
        f"Deterministic route:   "
        f"{handled / total * 100:.2f}%"
    )

    deterministic_latencies = [
        r["latency"]
        for r in results
        if r["route"] == "DETERMINISTIC"
    ]

    if deterministic_latencies:

        avg_latency = (
            sum(deterministic_latencies)
            / len(deterministic_latencies)
        )

        print(
            f"Avg deterministic latency: "
            f"{avg_latency:.6f}s"
        )

    print("\n" + "=" * 70)
    print("DECISION")
    print("=" * 70)

    if handled > 0:

        print(
            """
KEEP

Structured numerical questions are routed to
deterministic Pandas analytics instead of asking
the LLM to calculate from a Top-K retrieved subset.

This provides:
- deterministic answers
- very low computation latency
- fewer LLM calls
- no dependency on retrieved context for calculations
"""
        )

    else:

        print("NO DETERMINISTIC ROUTES DETECTED.")


if __name__ == "__main__":
    main()